INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_what-is-ingot-ui', 'what-is-ingot-ui', 'What is Ingot UI?', 'Ingot UI is a library of dashboard design systems for founders and developers. Each system is a complete product look: tokens, components, charts and full page templates, as React 19 + Tailwind CSS v4 code and as editable Figma layers.
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_who-is-it-for', 'who-is-it-for', 'Who is Ingot UI for?', 'Founders and developers building a SaaS dashboard, admin panel or internal tool who want it to look finished without a designer, and teams whose AI agent writes most of the UI.
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_how-to-start', 'how-to-start', 'How do I get started?', '1. [Create a free account](/sign-up) (email and password, no card).
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_create-account', 'create-account', 'How do I create an account?', 'Open [Sign up](/sign-up) and enter your name, email and a password of at least 8 characters. There is no card and no email code. A free account gives you unlimited copies of free components, the Loopo system, API keys for the MCP server and 50 MCP calls a day.', 'sign up, signup, register, create account, new account, join, open account, account khulbo, registration', 'Getting started', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_need-account-to-browse', 'need-account-to-browse', 'Do I need an account to browse?', 'No. Anyone can browse and preview every component, system and template. Without an account you can copy or download 5 items; after that a free account is needed. Pro items need a paid plan to copy.', 'browse without account, guest, anonymous, no login, preview, look around, try without signing up', 'Getting started', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_formerly-foundry-ui', 'formerly-foundry-ui', 'Is Ingot UI the same as Foundry UI?', 'Yes. Foundry UI was renamed Ingot UI on 10 November 2026. Same product, same team, now at ingotui.com. See the [changelog](/changelog).', 'foundry ui, foundryui, renamed, old name, rebrand, same company, name change', 'Getting started', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_browse-library', 'browse-library', 'How do I find a component?', 'Use the search on the [home page](/) or browse by [category](/categories) and by [system](/systems). Every component has its own page with a live preview, facts and, where available, the code and a Copy to Figma button.
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_save-items', 'save-items', 'How do saved items work?', 'Press Save to your library on any component page. Saved items and your recent copies appear on [Saved](/saved). They are kept in this browser only for now, so they don''t follow you to another device or browser.', 'save, saved, bookmark, favourite, favorite, shortlist, recent copies, my library, saved items gone', 'Getting started', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_onboarding-checklist', 'onboarding-checklist', 'What is the setup checklist on my account?', 'It walks you through three steps: pick the system your product will use, connect your AI agent with an API key, and get your first component into your project (copy, install or ask your agent to scaffold a screen). Each step ticks itself off when it happens.', 'checklist, onboarding, steps, welcome, getting set up, progress', 'Getting started', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_templates-free', 'templates-free', 'Are the dashboard templates free?', 'Yes. Every full dashboard template on [Templates](/templates) is free with an account, whatever system it comes from: copy it as React code checked against its Figma screen, or paste it into Figma as editable layers.', 'templates, dashboard templates, full page, screens, free template, page template, admin template, starter', 'Getting started', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_what-is-in-pro', 'what-is-in-pro', 'What do I get with a paid plan?', 'Pro, Team and Lifetime unlock every design system, every component in code and Figma, and unlimited MCP calls. Team gives that to 5 people on one bill; Lifetime gives it to one person forever for one payment. Compare them on [Pricing](/pricing).', 'what do i get if i pay, paid plan benefits, pro features, paid features, what is included, unlock, premium, pro te ki ache', 'Getting started', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_is-it-open-source', 'is-it-open-source', 'Is Ingot UI open source?', 'No. Free components can be used by anyone with an account, for commercial work too, but the library is not open source and may not be redistributed. The full terms are on the [licence page](/license).', 'open source, opensource, github, source code, mit, free software, public repo', 'Getting started', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_compare-tools', 'compare-tools', 'How does Ingot UI compare to shadcn/ui, Untitled UI, Tremor or Tailwind Plus?', 'Side-by-side pages with sources are on [Compare](/compare). In short: shadcn/ui is a free, open-source base you style yourself; Ingot UI gives you finished dashboard systems on the same React and Tailwind stack, Figma layers that match the code, and an MCP server that keeps your agent on one system. Free Ingot UI components install with the shadcn CLI, so you can use both.', 'compare, comparison, vs, versus, alternative, shadcn, untitled ui, tremor, tailwind plus, tailwind ui, aceternity, magic ui, flowbite, preline, difference, better', 'Getting started', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_how-components-are-made', 'how-components-are-made', 'How are the components made?', 'Each system started as a complete set of real product screens. Components are taken from those screens in Figma, converted to React and Tailwind code that uses the system tokens and Ingot icons, and compared pixel by pixel with the Figma original before they are published. The score is on each component page. More on [About](/about).', 'how made, quality, checked, pixel match, figma original, qa, process, about, ai generated', 'Getting started', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_component-count', 'component-count', 'How many components are there?', 'More than 2,600 components across nine design systems, and over 2,300 of them have React code that passed a visual check against Figma. The rest are in Figma while their code is converted. New components are added every week; the live counts are on the [home page](/) and each [system page](/systems).', 'how many components, number, count, total, size of library, 2000, 1900, components koyta', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_component-categories', 'component-categories', 'What kinds of components are there?', 'Dashboard parts: KPI and stat cards, charts, tables and lists, cards and panels, modals, drawers, popovers, menus, forms, headers, navigation (sidebars, tabs), editors, feedback states, plus full page templates. Browse them by [category](/categories).', 'categories, types, kinds, what components, which components, list, modal, drawer, table, chart, form, sidebar, card', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_code-or-figma-only', 'code-or-figma-only', 'Why does a component have Figma but no code?', 'Its React code is still being converted and checked against the Figma original. Components without a passed check show Figma only. Save it on its page and it will be easy to find when the code lands; most components already have code.', 'no code, figma only, code missing, code not available, being converted, coming soon, cant copy code', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_qa-score', 'qa-score', 'What does checked against Figma mean?', 'Every generated component is rendered and compared pixel by pixel with its Figma original before it is published, and the match score is shown on its page. It checks the look; it does not test behaviour or accessibility.', 'qa, score, pixel, checked, verified, accuracy, match, quality badge, percent', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_live-preview', 'live-preview', 'Is the preview on the component page real code?', 'Yes. Component pages show a live render of the published code, not a picture of the design. The preview is free to explore even for Pro components.', 'preview, live preview, demo, render, screenshot, image, real code', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_copy-code-website', 'copy-code-website', 'How do I copy a component''s code?', 'Open the component page and use the copy button in the code panel. Generated components are one self-contained `.tsx` file that uses the system''s colours, type and Ingot icons. Free items count towards the 5 guest copies until you sign in; Pro items need Pro, Team or Lifetime.', 'copy code, get code, code copy, download code, tsx, source, how to copy, code nibo, copy button', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_component-charts', 'component-charts', 'Do you have chart components?', 'Yes. Bar, line, donut, stacked, meter and ranked-list charts, styled per system, plus hundreds of chart cards in the systems. See [Charts](/charts). With the MCP server, `get_chart` picks the right chart for a question and wires it to your data shape. They are our own components, not Recharts or Chart.js.', 'chart, charts, graph, bar chart, line chart, pie, donut, analytics chart, recharts, chart.js, visualisation', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_component-tables', 'component-tables', 'Is there a data table?', 'Yes. The free Loopo system has a `data-table` component, and every system has table and list components. Server-side pagination, filters in the URL, bulk select and CSV export are on the [roadmap](/roadmap) under Next.', 'table, data table, datagrid, grid, list, rows, pagination, sorting, filter, csv export', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_component-customise', 'component-customise', 'Can I change a component after I copy it?', 'Yes. It is plain React and Tailwind code in your repo, so you can edit anything. To change the look everywhere at once, edit the `--fu-*` tokens instead of single components. See [Tokens](/docs#tokens) or the [theme generator](/theme).', 'customize, customise, edit, change, modify, own the code, adjust, style, override', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_component-dependencies', 'component-dependencies', 'What do the components depend on?', 'React 19 and Tailwind CSS v4. Interactive parts such as dialogs, menus and selects use Base UI (`@base-ui/react`). Shared helpers (`cx`, icons, tokens) come with `init`. When you install with the shadcn CLI or `add_components`, the npm install command for any extra package is included.', 'dependencies, packages, base ui, radix, headless, requirements, peer dependencies, what to install', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_typescript-support', 'typescript-support', 'Are the components TypeScript?', 'Yes. Components are `.tsx` files. Using plain JavaScript is not something we provide; you would need to strip the types yourself.', 'typescript, ts, tsx, javascript, js, jsx, types', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_marketing-pages', 'marketing-pages', 'Do you have landing page or marketing sections?', 'No. Ingot UI is dashboard-only: app screens, admin panels and internal tools. There are no hero, pricing or marketing-site sections.', 'landing page, marketing, website sections, hero, homepage, pricing section, saas landing, blocks', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_component-responsive', 'component-responsive', 'Are the components responsive?', 'Components come from desktop dashboard screens and render at the size you give them. Check the live preview at your breakpoints and arrange layouts for small screens in your own page. If a component breaks on mobile, report it through [Support](/support#contact).', 'responsive, mobile, tablet, breakpoints, small screen, phone, adaptive', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_request-component', 'request-component', 'Can I request a component?', 'Yes. Write what you need through [Support](/support#contact), or let your agent call `send_feedback` through the MCP server. Requests decide what we build next.', 'request component, suggest component, missing component, need a component, can you add, please add, wish, upload component', 'Components', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_design-systems', 'design-systems', 'Which design systems are included?', 'Nine dashboard systems: Loopo (free), MailPulse, Auton, Axon, Veriq, Vantage, Montra, Spendix and Abotix. Each has its own colours, type, components, charts and page templates. Loopo is free; the others come with Pro, Team or Lifetime. See [Systems](/systems).', 'design systems, list all systems, all systems, which systems, loopo, mailpulse, auton, axon, veriq, vantage, montra, spendix, abotix, how many systems, nine, six', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_loopo-system', 'loopo-system', 'What is the Loopo system?', 'Loopo is the free system: a light analytics look with warm orange data, pill buttons, soft hairline cards and Geist type. It includes hand-built primitives (buttons, inputs, selects, dialogs, menus), charts, KPI cards, a data table and generated components. [Open Loopo](/systems/loopo).', 'loopo, free system, orange, analytics system, free design system', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mailpulse-system', 'mailpulse-system', 'What is MailPulse?', 'A Pro system for newsletter and audience-growth products: violet accents, square heat cells and dual-tone icons. [Open MailPulse](/systems/mailpulse).', 'mailpulse, newsletter, email marketing, violet, purple, audience', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_auton-system', 'auton-system', 'What is Auton?', 'A Pro system for operations and automation dashboards, an automation control room look in blue. [Open Auton](/systems/auton).', 'auton, automation, operations, workflows, agents console, blue', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_axon-system', 'axon-system', 'What is Axon?', 'A Pro system for data-dense products with calm chrome, in teal. [Open Axon](/systems/axon).', 'axon, data dense, teal, green, product analytics, runs', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_veriq-system', 'veriq-system', 'What is Veriq?', 'A Pro system for verification, trust and compliance dashboards, in indigo. [Open Veriq](/systems/veriq).', 'veriq, verification, compliance, kyc, trust, secrets, access, indigo', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_vantage-system', 'vantage-system', 'What is Vantage?', 'A Pro admin dashboard system built from the Vantage Admin screens, in rose red. [Open Vantage](/systems/vantage).', 'vantage, admin, crm, customers, red, rose, admin panel', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_montra-system', 'montra-system', 'What is Montra?', 'A Pro business finance system: cash position, transactions, budgets, invoices, forecasts and cash flow, in neutral greys with a blue series palette. [Open Montra](/systems/montra).', 'montra, finance, fintech, banking, cash flow, budget, invoices, accounting', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_spendix-system', 'spendix-system', 'What is Spendix?', 'A Pro company spend system: cards, requests, approvals, subscriptions and team spending, with slate type and a blue accent. [Open Spendix](/systems/spendix).', 'spendix, spend management, expenses, corporate cards, approvals, subscriptions', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_abotix-system', 'abotix-system', 'What is Abotix?', 'A Pro AI security system: threat monitoring, vulnerabilities, attack paths, AI pentests, agents, policies and compliance. [Open Abotix](/systems/abotix).', 'abotix, security, cybersecurity, threats, vulnerabilities, soc, ai security, pentest', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_which-system', 'which-system', 'Which system should I pick?', 'Pick the one closest to your product: Loopo for analytics, MailPulse for email and audiences, Auton for automation, Axon for dense data, Veriq for compliance, Vantage for admin, Montra for finance, Spendix for spend and Abotix for security. You can change the colours of any system with the [theme generator](/theme). Not sure? Start free with Loopo.', 'which system, choose, pick, best system, recommend, suggestion, kon ta nibo, which one', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_switch-systems', 'switch-systems', 'Can I switch or mix systems?', 'Yes. Systems share the same `--fu-*` token names, so swap the system CSS file to switch, or scope one per area with `data-system="loopo"`. Generated Pro components carry their system''s look inside the file, so mixing them on one screen will look mixed.', 'switch system, change system, mix systems, combine, multiple systems, data-system, two systems', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_new-systems', 'new-systems', 'Will more systems be added?', 'Yes. Systems have been added since launch (Montra, Spendix and Abotix), and new components arrive every week. Pro, Team and Lifetime include new systems at no extra cost. Follow the [changelog](/changelog).', 'add more systems, more systems, new systems, future systems, upcoming systems, next system', 'Design systems', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_install-cli', 'install-cli', 'How do I install the components?', 'Three ways:
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_shadcn-registry', 'shadcn-registry', 'Can I install with shadcn?', 'Yes. Every free component is a shadcn registry item, for example `npx shadcn add https://ingotui.com/r/button.json` or `https://ingotui.com/r/kpi-card.json`. Dependencies such as `cx` and the icons come along. Pro components come from the website or the MCP server with your API key, not from the public registry.', 'shadcn, registry, shadcn add, shadcn cli, components.json, shadcn ui, r json', 'Code and install', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_frameworks', 'frameworks', 'Which frameworks does it work with?', 'Components are plain React 19 and Tailwind CSS v4 files, so they work in Next.js, Vite and Remix. Interactive parts use Base UI. Vue, Svelte and Angular are not supported; Vue versions are on the [roadmap](/roadmap) under Later.', 'framework, react, nextjs, next.js, vite, remix, vue, svelte, angular, astro, requirements, compatible, support', 'Code and install', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_tokens-theming', 'tokens-theming', 'How do theming and design tokens work?', 'Each system is a set of `--fu-*` CSS variables. The theme bridge maps them to Tailwind utilities such as `bg-fu-surface` and `text-fu-ink`. Import both after Tailwind in your global CSS:
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_tailwind-v4-required', 'tailwind-v4-required', 'Do I need Tailwind CSS v4?', 'Yes. The tokens use Tailwind v4''s CSS-first `@theme` setup, so components expect Tailwind CSS v4. Tailwind v3 projects need to upgrade first (Tailwind''s own upgrade tool helps).', 'tailwind v4, tailwind 4, tailwind v3, tailwind 3, tailwind version, upgrade tailwind, tailwind config, postcss', 'Code and install', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_react-version', 'react-version', 'Which React version do I need?', 'The components are written for React 19. Older React versions are not listed as supported. If npm stops with an `ERESOLVE` peer dependency error, update the shadcn CLI and try again, or add `--legacy-peer-deps`.', 'react 19, react 18, react version, react 17, older react, compatibility', 'Code and install', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_nextjs-setup', 'nextjs-setup', 'How do I use it in a Next.js App Router project?', '1. Have Tailwind CSS v4 set up.
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_vite-setup', 'vite-setup', 'How do I use it with Vite?', 'Set up Tailwind CSS v4 with its Vite plugin, then install components and import `theme.css` plus a system file in your main CSS after `@import "tailwindcss";`. Everything else is plain React.', 'vite, react vite, cra, create react app, setup vite, vite plugin', 'Code and install', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_file-locations', 'file-locations', 'Where do the installed files go?', 'Components are written to `components/ingot/` and tokens to `styles/ingot/` (for example `styles/ingot/theme.css` and `styles/ingot/loopo.css`). Generated Pro components go to `components/ingot/<system>/`. Move them anywhere; fix the imports if you do.', 'where files, folder, path, directory, location, components ingot, styles ingot, file structure', 'Code and install', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_pro-code-install', 'pro-code-install', 'How do I install Pro components?', 'Pro components are not in the public registry. On Pro, Team or Lifetime, copy the code from the component page, or connect the [MCP server](/mcp) with your API key and ask your agent to add them (`add_components` or `get_component_code`).', 'pro install, install pro, pro components cli, paid components, premium install, pro code', 'Code and install', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_theme-generator', 'theme-generator', 'How do I make a system match my brand?', 'Use the free [theme generator](/theme): pick your brand colour, greys, corners, font and density. It checks WCAG AA contrast, builds a colour-blind-aware chart palette and exports CSS variables, a Tailwind v4 `@theme` block or DTCG JSON. No account needed.', 'brand colour, brand color, theme generator, custom colors, rebrand, palette, my colours, change color', 'Code and install', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_without-tailwind', 'without-tailwind', 'Can I use the components without Tailwind?', 'No. The components are written with Tailwind CSS v4 utility classes, so Tailwind v4 is required. The token file itself is plain CSS variables if you only need the colours.', 'without tailwind, no tailwind, css modules, styled components, plain css, bootstrap', 'Code and install', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_global-css-missing', 'global-css-missing', 'My components have no colours or look unstyled. What did I miss?', 'Usually the CSS imports. In your global CSS, after `@import "tailwindcss";`, add `@import "./styles/ingot/theme.css";` and a system file such as `@import "./styles/ingot/loopo.css";`, with paths relative to that CSS file. Without them, utilities like `bg-fu-surface` do nothing.', 'unstyled, no styles, no styles at all, no colours, no colors, css not working, classes not applied, bg-fu-surface not working, style missing, looks plain', 'Code and install', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_copy-to-figma', 'copy-to-figma', 'How do I copy a component to Figma?', '1. Open the component or template page.
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_figma-kit', 'figma-kit', 'Is there a full Figma kit file?', 'Every component lives in its system''s Figma library and can be pasted into your file from its page, or built in your file by your agent with `get_figma_design`. Downloadable kit files are not open yet; component pages say so. Need a whole file for a project? Write to support@ingotui.com.', 'figma kit, figma file, download figma, figma library, fig file, community file, duplicate, figma download', 'Figma', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_figma-paste-issue', 'figma-paste-issue', 'Copy to Figma does not paste anything. What can I do?', '1. Paste right after copying, into a Figma design file (not FigJam or Slides).
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_figma-agent-build', 'figma-agent-build', 'Can my AI agent build designs in Figma?', 'Yes. With both the Ingot UI MCP server and the Figma MCP connected, ask your agent to use `get_figma_design` for a component or template. It returns programs that the Figma MCP tool runs in your file, creating real, editable layers. Find slugs with `search_components`.', 'figma mcp, agent figma, get_figma_design, use_figma, design in figma with ai, figma automation, generate figma', 'Figma', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_figma-variables', 'figma-variables', 'Do the Figma components use variables?', 'The systems are built from tokens that match the `--fu-*` code variables. For variable collections in your own file, the [theme generator](/theme) exports DTCG JSON that Figma variable import plugins such as Tokens Studio read. Figma Code Connect is on the [roadmap](/roadmap) under Later.', 'figma variables, tokens studio, variable modes, styles, figma tokens, dtcg, design tokens figma', 'Figma', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_figma-free-vs-pro', 'figma-free-vs-pro', 'Which Figma items can I copy for free?', 'Loopo components and every dashboard template, with a free account (5 copies before you sign up). Components from the Pro systems need Pro, Team or Lifetime.', 'figma free, free figma, figma pro, locked figma, figma upgrade, figma limit', 'Figma', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_figma-missing-fonts', 'figma-missing-fonts', 'Figma says fonts are missing after I paste.', 'The systems use Geist, and some use Inter or Manrope. Install those free fonts on your computer (or use them from Figma''s font list) and the text renders as designed. Until then Figma shows a missing-font warning but the layers stay editable.', 'missing fonts, font missing, geist, inter, manrope, wrong font, text looks different figma', 'Figma', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_figjam', 'figjam', 'Does it work with FigJam, Sketch or Penpot?', 'Copy to Figma targets Figma design files only. FigJam, Figma Slides, Sketch, Penpot and Adobe XD are not supported.', 'figjam, sketch, penpot, adobe xd, framer, other design tools', 'Figma', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_icons-overview', 'icons-overview', 'What icons are included?', 'More than 11,000 icons in six styles (stroke, sharp, solid, duotone, twotone and bulk) on one 24px grid with a 1.5px stroke. Search them on [Icons](/icons) and copy SVG or JSX, or download.', 'icons, icon set, how many icons, svg icons, icon library, 7000 icons, 11000 icons, styles, icon pack', 'Icons', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_icons-free', 'icons-free', 'Are the icons free?', 'Yes. Every icon is free on every plan, for commercial work too. Without an account, icon copies count towards the 5 guest copies.', 'icons free, free icons, icon price, icon cost, pay for icons', 'Icons', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_icons-copy', 'icons-copy', 'How do I use an icon in my code?', 'On [Icons](/icons), pick an icon and a style, then copy SVG (works anywhere, including Figma as vectors) or JSX. In projects set up with `init`, components use `<Icon name="..." />` from `components/ingot/icons`.', 'use icon, icon in react, use icon react, copy svg, jsx icon, icon component, import icon, download svg', 'Icons', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_icons-package', 'icons-package', 'Is there an npm package for the icons?', 'The icon page shows JSX imports from `ingotui-icons/react/<style>`. That package is not on the public npm registry yet, so copy SVG or JSX from [Icons](/icons) for now, or let your agent use `search_icons`.', 'ingotui-icons, icon package, npm icons, install icons, icons npm, npm install icons', 'Icons', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_icons-licence', 'icons-licence', 'What is the icon licence?', 'Use the icons in unlimited personal and commercial products under the [Ingot UI licence](/license). Some icons come from open-source sets under their own licences, listed in the package licence files. Don''t resell or redistribute the icons as an icon set.', 'icon license, icon licence, attribution, credit, hugeicons, third party, mit icons', 'Icons', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_icons-in-figma', 'icons-in-figma', 'Can I use the icons in Figma?', 'Yes. Copy an icon as SVG on [Icons](/icons) and paste it into Figma: it arrives as an editable vector. Icons inside pasted components come in as vectors too.', 'icons figma, icon vectors figma, svg into figma, vector icons', 'Icons', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_icons-search-agent', 'icons-search-agent', 'Can my agent find icons?', 'Yes. The MCP tool `search_icons` finds Ingot icons by name in any of the six styles and returns the JSX.', 'search_icons, agent icons, mcp icons, find icon, icon search', 'Icons', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_connect-mcp', 'connect-mcp', 'How do I connect the MCP server to my AI agent?', '1. Sign in and open the [MCP page](/mcp); one button creates your API key and the config for your client.
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-what-is', 'mcp-what-is', 'What is the MCP server and why use it?', 'MCP (Model Context Protocol) lets AI coding agents call tools. The Ingot UI MCP server gives your agent the design tokens, checked React components, charts, icons, Figma builds and a UI audit, so the screens it writes come from one system instead of guesses. It is a remote server; nothing to install.', 'what is mcp, why mcp, why use mcp, use mcp, mcp meaning, model context protocol, benefit, how does mcp work', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-claude-code', 'mcp-claude-code', 'How do I add Ingot UI to Claude Code?', 'Run this in your terminal with your key from [Account](/account):
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-cursor', 'mcp-cursor', 'How do I add Ingot UI to Cursor?', 'Use the one-click install link on the [MCP page](/mcp), or paste this into `~/.cursor/mcp.json`:
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-vscode', 'mcp-vscode', 'How do I add Ingot UI to VS Code (GitHub Copilot)?', 'Use the one-click install link on the [MCP page](/mcp), or add this to `.vscode/mcp.json`:
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-codex', 'mcp-codex', 'How do I add Ingot UI to Codex?', 'Paste this at the end of `~/.codex/config.toml`, then restart Codex:
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-other-clients', 'mcp-other-clients', 'Does it work with Windsurf, Claude Desktop or other clients?', 'Ready configs exist for Claude Code, Cursor, VS Code and Codex. Any other client that supports remote MCP servers over Streamable HTTP with an Authorization header works too: use `https://mcp.ingotui.com/mcp` and `Authorization: Bearer YOUR_API_KEY`. Clients that can''t send a custom header can''t connect yet; sign-in without a key (MCP OAuth) is on the [roadmap](/roadmap).', 'windsurf, claude desktop, zed, cline, roo, continue, jetbrains, other client, chatgpt, gemini cli, lovable, bolt, v0', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_api-key', 'api-key', 'Where do I get an API key?', 'Sign in, open [Account](/account) and create a key under API keys, or use the connect button on the [MCP page](/mcp). Keys start with `fu_`, are shown once and are stored only as a hash, so copy it right away. Lost it? Create a new one and revoke the old one.', 'api key, key, token, bearer, authorization, create key, generate key, fu_, lost key, api key kothay', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_revoke-key', 'revoke-key', 'How do I revoke or replace an API key?', 'Open [Account](/account), find the key under API keys and press Revoke. It stops working at once. Create a new key and update your agent''s config. If a key leaked (for example in a public repo), revoke it straight away.', 'revoke key, delete key, leaked key, pushed key to github, committed key, key by mistake, rotate key, replace key, key exposed, compromised', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-key-safety', 'mcp-key-safety', 'Is the API key safe? What can it do?', 'The key only reads the Ingot UI library for your account and counts your plan''s limit. It can''t change your account, see your code or make payments. It is stored only as a SHA-256 hash. Don''t commit it to a repo or share it; one plan is for one person.', 'key safe, security, permissions, what can key do, scope, sha-256, privacy key, share key', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-limits', 'mcp-limits', 'Is there a limit on MCP calls?', 'Free accounts get 50 MCP calls a day, counted per account and reset at 00:00 UTC. Pro, Team and Lifetime are unlimited. Your agent can check its plan and today''s calls with `get_usage`.', 'mcp limit, how many calls, how many mcp calls, free calls, mcp calls, quota, 50 calls, daily limit, unlimited, reset time', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-limit-reached', 'mcp-limit-reached', 'My agent says Daily limit reached.', 'The Free plan''s 50 MCP calls for today are used up. The count resets at 00:00 UTC, or upgrade on [Pricing](/pricing) for unlimited calls. Each tool call counts once.', 'daily limit reached, limit reached, quota exceeded, too many calls, mcp stopped', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-401', 'mcp-401', 'The MCP server says Missing or invalid API key (401).', '1. Check the header is exactly `Authorization: Bearer fu_...` with no quotes or spaces around the key.
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-pro-locked', 'mcp-pro-locked', 'My agent says a component is a Pro component.', 'Your account is on the Free plan, so Pro components are blocked; `add_components` lists them under `blocked`. Upgrade on [Pricing](/pricing), or ask for Loopo and template components instead. If you already paid, check that the key belongs to the account with the plan.', 'pro component, blocked, locked, mcp pro, upgrade required, is a pro component, cant get component', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-not-connecting', 'mcp-not-connecting', 'My agent doesn''t show the Ingot UI tools.', '1. Restart the client after adding the config.
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-tools', 'mcp-tools', 'Which tools does the MCP server have?', '`list_design_systems`, `get_design_system`, `get_tokens`, `search_components`, `get_component`, `get_component_code`, `add_components`, `init_project`, `scaffold_screen`, `get_figma_design`, `get_chart`, `search_icons`, `audit_ui`, `get_usage` and `send_feedback`. What each does is on the [MCP page](/mcp).', 'tools, mcp tools, which tools, list of tools, functions, what tools, capabilities', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_agent-first-steps', 'agent-first-steps', 'What should I ask my agent first?', 'Ask it to run `init_project` first. It writes the tokens, the theme bridge and rules files, so later sessions keep using the system. Then ask for a screen, for example: "Build an analytics overview page with KPI cards, a capsule bar chart for monthly revenue and a transactions table. Run audit_ui before you finish."', 'init project, init_project, first prompt, prompt, what to ask, first steps, example prompt', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-rules-files', 'mcp-rules-files', 'How does my agent stay on the design system in later sessions?', '`init_project` writes `CLAUDE.md`, `AGENTS.md` and `.cursor/rules/ingot.mdc` with short rules: build from Ingot components, use the `--fu-*` tokens, never raw hex colours, and run `audit_ui` before finishing. Agents read those files at the start of every session. Re-running it updates the block in place.', 'rules, claude.md, agents.md, cursor rules, mdc, ingot.md, keep agent on system, consistency, memory', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_scaffold-screen', 'scaffold-screen', 'Can the agent build a whole screen?', 'Yes. `scaffold_screen` turns a screen description into a page assembled from library components, and `add_components` returns the files plus the npm install command. Ask in plain words, for example "a customers page with a table and a detail drawer".', 'scaffold, build screen, generate page, whole page, full screen, ai build dashboard, make a page', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_audit-ui', 'audit-ui', 'What does audit_ui do?', 'It checks your UI code for hard-coded colours and off-system patterns, so the agent can fix them before finishing. The rules file asks the agent to run it on every file it touched.', 'audit, audit_ui, lint, check code, hard coded colors, hex colours, off system, design lint', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-test', 'mcp-test', 'How do I test that the MCP connection works?', 'Ask your agent: "List the Ingot UI design systems." It should call `list_design_systems` and show the nine systems. Your onboarding checklist ticks the step when the first call arrives.', 'test connection, check mcp, verify, is it working, first call, test prompt', 'MCP and AI agents', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_cli-commands', 'cli-commands', 'What does the ingotui CLI do?', 'The docs show three commands:
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_cli-not-found', 'cli-not-found', 'npx ingotui says 404 or package not found.', 'The `ingotui` package is not available on the public npm registry right now. Install the same free components with shadcn instead, for example `npx shadcn add https://ingotui.com/r/tokens.json https://ingotui.com/r/button.json`, or connect your agent to the [MCP server](/mcp). We''ll update this answer when the package is live.', '404, not found, npm error, e404, ingotui not found, package does not exist, npx fails, cli error, could not determine executable', 'CLI', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_cli-pro', 'cli-pro', 'Can the CLI install Pro components?', 'No. The CLI and the public registry serve free components only. On a paid plan, get Pro components from the component page or through the [MCP server](/mcp).', 'cli pro, pro cli, install pro cli, paid components cli, cli locked', 'CLI', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_cli-overwrite', 'cli-overwrite', 'The CLI skipped a file that already exists.', 'It never overwrites by default. Add `--force` to replace existing files, for example `npx ingotui add button --force`. Add `--install` to run the npm install for the dependencies as well.', 'skip, exists, overwrite, --force, force, already exists, --install, replace file', 'CLI', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_cli-options', 'cli-options', 'Can I change where the CLI writes files?', 'Yes. Set `INGOT_DIR` to the project folder, for example `INGOT_DIR=apps/web npx ingotui add button`. Files go to `components/ingot/` and `styles/ingot/` inside it. The CLI needs Node 18 or newer.', 'ingot_dir, directory, monorepo, path, node version, node 18, environment variable, custom folder', 'CLI', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_cli-after-init', 'cli-after-init', 'What do I do after init?', 'Add the two imports to your global CSS after `@import "tailwindcss";`:
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_eresolve', 'eresolve', 'npm stops with ERESOLVE or a peer dependency error.', 'Some packages don''t list your React version as a peer yet. Update the shadcn CLI (`npx shadcn@latest`) and try again; with npm you can add `--legacy-peer-deps`. pnpm, yarn and bun usually don''t need it.', 'eresolve, peer dependency, peer deps, npm error, legacy-peer-deps, force, conflicting peer, dependency conflict', 'CLI', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_shadcn-components-json', 'shadcn-components-json', 'shadcn asks for components.json or fails to add.', 'The shadcn CLI needs a set-up project. Run `npx shadcn@latest init` once, then `npx shadcn@latest add https://ingotui.com/r/button.json`. Make sure the URL ends in `.json` and the component is a free one; Pro components are not in the public registry.', 'components.json, shadcn init, shadcn error, shadcn add failed, registry error, not found in registry', 'CLI', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_module-not-found', 'module-not-found', 'I get Module not found for @base-ui/react or cx.', 'Install the missing package: `npm install @base-ui/react`. For `cx`, `icons` or tokens, add them too: `npx shadcn add https://ingotui.com/r/cx.json https://ingotui.com/r/icons.json`. The files import each other relatively (for example `./icons`), so keep them together in `components/ingot/`.', 'module not found, cannot find module, base-ui, base ui, cx not found, import error, alias, @/ path', 'CLI', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_pricing-plans', 'pricing-plans', 'How much does Ingot UI cost?', 'Free is $0. Pro is for one person, Team is for 5 people on one bill, and Lifetime is one payment for one person, forever. At the time of writing Pro is $39 a year, Team $129 a year, and Lifetime $49 at the launch deal (then $99). The current prices, spots left and any end date are always on [Pricing](/pricing). Every paid plan has a 7-day refund.', 'price, cost, how much, pricing, prices, koto taka, dam koto, price list', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_free-components', 'free-components', 'What do I get for free?', 'With a free account: the Loopo system, the free components in React code, every dashboard template, every icon, Copy to Figma for those items and the MCP server with 50 calls a day. Free components are free forever, for commercial use too. No card needed. [Create an account](/sign-up).', 'free, free plan, free tier, what is free, get for free, gratis, free version', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_pro-plan', 'pro-plan', 'What is Pro?', 'Pro is for one person: all nine design systems, every component in code and Figma, unlimited MCP calls and new components every week. It is billed yearly; the price is on [Pricing](/pricing). Building with others? See Team.', 'pro, pro plan, pro yearly, upgrade to pro, pro features, premium', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_lifetime-deal', 'lifetime-deal', 'What is the Lifetime deal?', 'Lifetime is one payment for everything in Pro, for one person, forever, including every future system and update and dark mode when it ships. At launch it costs less for a limited number of buyers (currently $49 for the first 100, then $99). The spots counter on [Pricing](/pricing) counts real paid orders, and any countdown runs to a real end date that never resets.', 'lifetime, ltd, lifetime deal, one time, one-time payment, pay once, launch deal, spots left, appsumo, forever, lifetime access', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_lifetime-meaning', 'lifetime-meaning', 'What does lifetime mean? Is it really forever?', 'Lifetime does not expire: every current and future design system and every update, for as long as Ingot UI runs. It is for one person. A later price change never applies to a Lifetime purchase already made.', 'lifetime forever, how long, expire, does lifetime expire, lifetime updates, future updates, is lifetime real', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_deal-end', 'deal-end', 'When does the launch deal end?', 'When the launch spots are taken, or at the end date if one is shown on [Pricing](/pricing), whichever comes first. After that Lifetime goes to its regular price. The counter and countdown are real and never reset.', 'deal end, deadline, countdown, how long deal, last day, spots, ends when, offer end, expiry', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_why-yearly', 'why-yearly', 'Why is Pro billed yearly and not monthly?', 'One payment a year keeps the price low; card fees on small monthly charges would push it up. Cancel any time and the plan stays on until the end of the year you paid for. Would rather pay once? Lifetime covers everything, forever.', 'monthly, per month, no monthly, pay monthly, month to month, mashik', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_which-plan', 'which-plan', 'Which plan should I pick?', 'Building alone: Pro, or Lifetime if you''d rather pay once. Building with a co-founder or first hires: Team, which covers 5 people on one bill. An agency or larger company: write to support@ingotui.com and we''ll set up the right seats and terms. Just exploring: Free.', 'which plan, best plan, recommend, choose plan, pro or lifetime, lifetime vs pro, team or pro, kon plan', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_upgrade', 'upgrade', 'How do I upgrade?', 'Open [Pricing](/pricing), choose the plan and pay on Contra with the same email you use on Ingot UI. Then open [Activate](/activate) (or Account → Activate) and confirm the plan. Your plan is usually switched on within an hour.', 'upgrade, how to upgrade, go pro, buy pro, unlock, upgrade plan, upgrade korbo', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_pro-to-lifetime', 'pro-to-lifetime', 'I have Pro. Can I switch to Lifetime?', 'Yes. Buy Lifetime on [Pricing](/pricing), activate it, then cancel the Pro subscription in your Contra purchases so it stops renewing. Checkout doesn''t credit the unused part of Pro automatically; write to support@ingotui.com within 7 days of the Pro payment if you want that refunded.', 'switch to lifetime, pro to lifetime, change plan, prorate, proration', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_try-before-buy', 'try-before-buy', 'Can I try before paying? Is there a trial?', 'There is no time-limited trial; the Free plan is the trial. Browse and preview every component, copy 5 items without an account, then use the free account for the Loopo system, templates and 50 MCP calls a day. Paid plans also have a 7-day refund.', 'trial, free trial, try first, try before paying, demo', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_discounts', 'discounts', 'Do you have discounts, coupons or student pricing?', 'There are no coupon codes or student or regional discounts right now. The current offer is the Lifetime launch deal on [Pricing](/pricing).', 'discount, coupon, promo code, voucher, student, education, ppp, regional pricing, cheaper, black friday, offer, chhar', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_agency-enterprise', 'agency-enterprise', 'Do you have an agency or enterprise plan?', 'Not as a checkout plan yet. If you need more than 5 seats, terms for client work, custom invoices or SSO, write to support@ingotui.com and we''ll set it up. An Agency plan is on the [roadmap](/roadmap) under Next.', 'agency plan, enterprise, company plan, bulk, many seats, sso, procurement, custom terms, volume', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_currency-tax', 'currency-tax', 'Which currency are prices in? Is tax included?', 'Prices are in USD. Tax is added at checkout where it applies.', 'currency, usd, dollar, euro, bdt, taka, tax, vat, sales tax, local currency, gst', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_price-changes', 'price-changes', 'Will my price go up later?', 'Price changes apply to new purchases only. A change never applies to a Lifetime purchase already made, and a subscription price change takes effect at your next renewal after we tell you. See the [terms](/terms#plans).', 'price go up, price increase, price change, locked price, price lock, grandfathered, renewal price', 'Pricing and plans', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_checkout-opening', 'checkout-opening', 'How do I pay?', '1. On [Pricing](/pricing), press the button for your plan. It opens checkout on Contra, our payment provider.
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_payment-provider', 'payment-provider', 'Who handles the payment? Why Contra?', 'Contra, the payments platform for independents, processes every order, charges you and emails your receipt; its terms also apply to the purchase. We never see your card number. Lemon Squeezy checkout is not live, so Contra is how plans are sold today.', 'contra, who processes payment, payment provider, lemon squeezy, stripe, merchant, is it safe to pay, secure payment', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_payment-methods', 'payment-methods', 'Which payment methods can I use?', 'Contra takes cards, Google Pay and Cash App Pay. Other methods such as PayPal, bank transfer, bKash or crypto are not offered. If none of these work for you, write to support@ingotui.com.', 'payment methods, card, credit card, debit card, visa, mastercard, paypal, google pay, cash app, bkash, nagad, bank transfer, crypto, apple pay', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_activate-plan', 'activate-plan', 'I paid. How do I activate my plan?', '1. Sign in to the Ingot UI account that should get the plan.
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_activation-wait', 'activation-wait', 'How long does activation take?', 'Usually within an hour. Once the Contra payment is matched, your plan switches on and you get an email; the [Activate](/activate) page checks every 20 seconds while it''s open. If it''s been several hours, write to support@ingotui.com with your Contra receipt.', 'how long, activation time, waiting, pending, still pending, not activated yet, delay, kotokkhon, when will it activate', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_activation-rejected', 'activation-rejected', 'It says we couldn''t match this payment.', 'We found no Contra payment for the details sent, usually because the email differs from the one used on Contra. Send a new request on [Activate](/activate) with the exact email you paid with, or reply to our email with your Contra receipt and we''ll sort it out.', 'rejected, couldnt match, payment not found, not matched, activation failed, declined request, wrong details', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_paid-without-account', 'paid-without-account', 'I paid before creating an account.', 'That works. We match the sale by your payer email: when it arrives we email that inbox a link to activate. Open it, create a free account with the same email (or sign in) and the plan switches on. Or create the account now and use [Activate](/activate).', 'paid without account, guest checkout, no account yet, claim, claim link, bought first, before sign up', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_claim-link', 'claim-link', 'The claim link says sign in with the email you paid with.', 'The purchase was paid with a different email from the account you''re signed in to. Sign out and sign in (or sign up) with the payer email, then open the link again. Want the plan on your other account? Reply to the purchase email and tell us.', 'claim, wrong account, different email, sign in with the email you paid with, claim page error', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_paid-wrong-email', 'paid-wrong-email', 'I paid with a different email from my account.', 'No problem. On [Activate](/activate), sign in to the account that should get the plan and type the email you paid with on Contra in the payment email field. We match the payment by that email.', 'different email, wrong email, another email, email mismatch, paid with other email', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_payment-failed', 'payment-failed', 'My payment failed or the card was declined.', 'The payment happens on Contra. Check the card details and your bank''s online-payment settings, or try another card, Google Pay or Cash App Pay. If money left your account but no Contra receipt arrived, write to support@ingotui.com with the date and amount.', 'payment failed, payment fail, declined, card declined, transaction failed, error at checkout, payment hocche na, money deducted', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_already-have-plan', 'already-have-plan', 'It says I already have this plan.', 'Your account already has a plan that covers it, so there''s nothing to buy or activate; everything it covers is unlocked. If you bought a different plan, use [Activate a different purchase](/activate?new=1).', 'already have, you already have, nothing to activate, already pro, already lifetime', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_activation-rate-limit', 'activation-rate-limit', 'It says Too many tries.', 'Activation requests are limited to 5 an hour per account. Wait an hour, or write to support@ingotui.com with your Contra receipt.', 'too many tries, rate limited, activation limit, wait an hour', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_refund-policy', 'refund-policy', 'Can I get a refund?', 'Yes. Every paid plan has a 7-day refund, no questions asked. Write to support@ingotui.com from the email you paid with (or reply to your receipt), with the order number if you have it. Refunds go through Contra to the card or wallet you paid with, usually within 2 business days; your bank may take 5 to 10 business days to show it. Your account then returns to Free. Details: [Refund Policy](/refund).', 'refund, money back, refund policy, 7 day refund, guarantee, taka ferot, refund chai', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_refund-after-7-days', 'refund-after-7-days', 'Can I get a refund after 7 days?', 'The promise covers 7 days from payment. Renewal payments after that are not refunded automatically, but if you were charged by mistake write to support@ingotui.com and we''ll look at it.', 'late refund, after 7 days, two weeks later, renewal refund, charged by mistake, forgot to cancel', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_cancel-subscription', 'cancel-subscription', 'How do I cancel Pro or Team?', 'Cancel from your purchases on Contra, or write to support@ingotui.com and we cancel it for you. Cancelling stops the next renewal; the plan stays on until the end of the period you paid for. Anything you already copied stays yours.', 'cancel, unsubscribe, stop subscription, renewal, end subscription, stop billing, cancel korbo, turn off auto renew', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_renewal', 'renewal', 'Does my plan renew automatically?', 'Pro and Team renew each period until you cancel; Lifetime is a single payment. Cancel any time from your Contra purchases or by writing to support@ingotui.com.', 'auto renew, renewal, recurring, renews, next payment, billing date, will i be charged again', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_invoices-receipts', 'invoices-receipts', 'Where do I find my invoice or receipt?', 'Contra emails a receipt right after you pay, and your payments are listed on [Account](/account). Need an invoice with your company name or VAT number? Write to support@ingotui.com with the details. Invoices with company details are on the [roadmap](/roadmap).', 'invoice, receipt, bill, vat, tax invoice, company details, billing history, proof of payment, memo', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_double-charged', 'double-charged', 'I was charged twice.', 'Write to support@ingotui.com from the email you paid with and include both Contra receipts. We refund the duplicate.', 'charged twice, double charge, duplicate payment, paid two times, extra charge', 'Payments and activation', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_commercial-use', 'commercial-use', 'Can I use Ingot UI in commercial and client projects?', 'Yes. Use the components in unlimited personal and commercial products: your SaaS, paid products with any number of users, and client work. There is no royalty, per-user fee or revenue limit. Free components need only a free account; Pro components need an active plan when you copy them. See the [licence](/license).', 'licence, license, license included, commercial license, commercial, commercial use, client work, client projects, client er kaj, saas, allowed, royalty', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_stop-paying', 'stop-paying', 'What happens to my code if I stop paying?', 'Everything you copied while your plan was active stays yours to use, in what you shipped and in new products. You only lose the ability to copy new Pro items. Free components stay free forever.', 'stop paying, expire, keep code, after subscription ends, lose access, cancel what happens, ownership', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_resell-library', 'resell-library', 'Can I resell or redistribute the components?', 'No. Ship them inside your own and your clients'' products, but don''t resell, share or redistribute the library or a substantial part of it on its own: as a UI kit, component library, template pack, theme, starter, Figma kit or icon set, paid or free. See the [licence](/license).', 'resell, redistribute, sell components, ui kit, marketplace, themeforest, gumroad, envato, share library', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_sell-templates', 'sell-templates', 'Can I sell a template or theme made with Ingot UI?', 'No. Templates, themes or starters where buyers get the source to build their own products are not allowed, on any plan.', 'sell template, sell theme, starter kit sale, boilerplate, template for sale, themeforest', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_client-handover', 'client-handover', 'Can I hand the code over to my client?', 'Yes. Build the product, hand it over with the source code, and the client may own, run and change it. Handing over doesn''t give the client a licence to the library itself: to copy new items, they need their own plan.', 'client handover, give code to client, client owns, deliver to client, freelance, agency client', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_open-source-use', 'open-source-use', 'Can I use it in an open-source project?', 'Free components can go in an open-source app. Publishing Pro component code in a public repository puts it where anyone can copy it, so write to support@ingotui.com first and we''ll tell you what works.', 'open source project, public repo, github public, oss, mit project, publish code', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_licence-teammates', 'licence-teammates', 'Can my teammates work on the code?', 'Yes. Teammates and contractors can read, change and deploy the code in your product''s repo. But a plan is for one person: anyone who copies Pro items from the site, CLI or MCP needs their own plan or a Team seat. Don''t share your account or API key.', 'teammates, share account, share login, colleagues, contractors, one plan one person, multiple developers', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_licence-ai-code', 'licence-ai-code', 'Is code my AI agent writes with the MCP covered?', 'Yes. Components your agent adds through the MCP server, CLI or registry count as copying by you, under the same terms and plan limits.', 'ai code licence, mcp licence, agent generated, ai output, copyright ai', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_licence-name-logo', 'licence-name-logo', 'Can I use the Ingot UI name or logo?', 'Not in a way that suggests we made or endorse your product. Attribution is not required.', 'logo, name, brand, attribution, credit, endorse, mention ingot', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_licence-version', 'licence-version', 'Which licence version applies to me?', 'Each version of the licence shows its number and effective date on the [licence page](/license). A new version applies to items you copy after its effective date; items copied earlier stay under the version that applied then.', 'licence version, terms change, which terms, effective date, licence update', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_licence-unsure', 'licence-unsure', 'My use case isn''t covered. Who do I ask?', 'Write to support@ingotui.com before you ship and describe the use. A written yes from us is part of your licence.', 'not sure licence, special case, ask permission, written permission, unusual use, edge case', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_free-copy-limit', 'free-copy-limit', 'Why am I asked to sign up after a few copies?', 'Without an account you can copy or download 5 items (code, Figma, SVG, PNG and installs all count). A free account removes that limit for free components, the Loopo system, templates and icons. [Create one](/sign-up) in a few seconds, no card needed.', 'limit, 5 copies, copy limit, sign up, without an account, blocked, free copies used, guest limit, cant copy anymore', 'Account and security', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_forgot-password', 'forgot-password', 'I forgot my password or cannot log in.', 'There is no self-service password reset yet. Write to support@ingotui.com from your account email and we''ll reset access. Also check that you''re using the same email you signed up with on [Log in](/sign-in).', 'login, sign in, password, forgot password, reset password, locked out, cant log in, wrong password, password bhule gechi', 'Account and security', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_sign-in-methods', 'sign-in-methods', 'Can I sign in with Google or GitHub?', 'No. Accounts use email and password only, with a password of at least 8 characters.', 'google login, github login, social login, sso login, oauth, magic link, sign in with google', 'Account and security', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_change-email', 'change-email', 'How do I change my email or name?', 'Changing the account email isn''t available on the Account page. Write to support@ingotui.com from your current email with the new address and we''ll change it.', 'change email, update email, change name, new email address', 'Account and security', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_two-factor', 'two-factor', 'Is there two-factor authentication?', 'Not yet. Use a strong, unique password and keep your API keys private.', '2fa, two factor, mfa, authenticator, security, otp', 'Account and security', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_delete-account', 'delete-account', 'How do I delete my account or data?', 'Email support@ingotui.com from your account email and ask for deletion. We remove your account, API keys and usage data, and confirm by email. Purchase records are kept as long as tax and accounting rules require. You can delete API keys yourself on [Account](/account) at any time.', 'delete account, close account, remove account, remove data, erase, gdpr delete, account delete korbo', 'Account and security', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_account-page', 'account-page', 'What can I do on the Account page?', '[Account](/account) shows your plan, payments, the Activate link for Contra purchases, your Team seats if you have Team, and your API keys (create, copy once, revoke).', 'account page, my account, dashboard, profile, settings, where is account', 'Account and security', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_sign-out', 'sign-out', 'How do I log out?', 'Use Sign out from the account menu. Signing out on one browser doesn''t revoke your API keys; revoke those on [Account](/account) if needed.', 'log out, logout, sign out, signout, switch account', 'Account and security', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_plan-not-showing', 'plan-not-showing', 'I''m signed in but Pro items are still locked.', '1. Check you''re signed in to the account that has the plan ([Account](/account) shows it).
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_team-plan', 'team-plan', 'Is there a plan for my team?', 'Yes. Team puts 5 people (the owner included) on one bill, each with everything in Pro and their own login, API keys and MCP. The owner buys it and invites up to 4 teammates by link from [Account](/account). The price is on [Pricing](/pricing). Need more than 5 seats? Write to support@ingotui.com.', 'team, team plan, seats, company, colleagues, co-founder, organisation, multiple users, 5 seats, team price', 'Team', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_team-invite', 'team-invite', 'How do I invite my co-founder or a teammate?', '1. Open [Account](/account) and type their email under Team.
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_team-invite-errors', 'team-invite-errors', 'My team invite link doesn''t work.', 'Common reasons: the link was used or cancelled (ask the owner for a new one), it''s for a different email (sign in with the invited email), the owner''s Team plan isn''t active, or you''re already on another team (leave it first on Account).', 'invite link not valid, invalid invite, invite not working, invite expired, different email invite, cant join team, join team error', 'Team', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_team-remove', 'team-remove', 'How do I remove someone from my team?', 'On [Account](/account), remove them under Team. Their Pro access ends straight away and the seat is free for someone new. Anything they already copied stays theirs to ship. You can also cancel a pending invite there.', 'remove member, remove teammate, kick, revoke seat, free seat, someone left', 'Team', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_team-leave', 'team-leave', 'How do I leave a team?', 'Members can leave from [Account](/account). Your Pro access from that team ends at once; your own account and anything you copied stay. Owners can''t leave their own team.', 'leave team, quit team, exit team, remove myself', 'Team', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_team-seats-full', 'team-seats-full', 'It says all seats are in use.', 'A Team has 5 seats including the owner, and pending invites count. Remove someone or cancel an invite to free a seat. Need more seats? Write to support@ingotui.com.', 'seats full, all seats in use, no seats left, more seats, 6 people, add more members', 'Team', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_team-ends', 'team-ends', 'What happens to members if the Team plan ends?', 'If the owner cancels, members keep access until the end of the paid period. When the Team ends, Pro items lock again for members; what they copied stays theirs. Restarting the Team restores access.', 'team ended, owner cancelled, team expired, members lost access, team inactive', 'Team', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_team-existing-plan', 'team-existing-plan', 'I already have a plan. Can I add seats for my team?', 'Yes. Buy Team to add seats for your teammates. On Pro, cancel it in your Contra purchases so you don''t pay twice; Team already includes you. On Lifetime, you keep it, and Team covers the others.', 'already have pro add team, add seats, upgrade to team, switch to team', 'Team', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_team-billing', 'team-billing', 'Does every Team member need their own plan?', 'Only the owner pays, one bill for the whole team. Members use a free account and get everything in Pro while they are on the team.', 'team owner pays, members free account, team cost per member, member plan', 'Team', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_contact-support', 'contact-support', 'How do I contact a person?', 'Write to support@ingotui.com or use the form on [Support](/support#contact). A person replies by email, usually within a day. For billing questions, write from the email you paid with.', 'contact, human, talk to a human, real person, live chat, manush, kotha bolte chai', 'Support', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_response-time', 'response-time', 'How fast do you reply?', 'Usually within a day, by email. Keep the ticket id from the form if you write again.', 'response time, how long reply, when will you answer, waiting for reply, no reply, sla', 'Support', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_ticket-id', 'ticket-id', 'What is the ticket id?', 'Messages from the support form or this chat become a ticket with an id such as T-XXXXXXXX. Mention it when you write again so we find your conversation fast.', 'ticket, ticket id, reference number, case number, follow up, my message', 'Support', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_bug-report', 'bug-report', 'How do I report a bug?', 'Use the form on [Support](/support#contact) with the page or component link, what you expected and what happened, plus your browser. Your agent can also report problems with the MCP tool `send_feedback`. Fixes are noted in the [changelog](/changelog).', 'bug, found a bug, report bug, report issue, glitch, bug report, something broken', 'Support', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_feature-request', 'feature-request', 'How do I suggest a feature?', 'Upvote it on the [roadmap](/roadmap) if it''s there, or send it through [Support](/support#contact). Agents can use `send_feedback`.', 'feature request, suggestion, idea, request feature, wishlist, feedback, improve', 'Support', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_support-rate-limit', 'support-rate-limit', 'The support form says too many messages.', 'The form allows a limited number of messages per network each hour. Try again in an hour, or email support@ingotui.com directly.', 'too many messages, form not sending, contact form error, message failed', 'Support', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_accessibility-report', 'accessibility-report', 'How do I report an accessibility problem?', 'Write through [Support](/support#contact) with the page link and what happened; your browser and any assistive technology help. We reply by email and note fixes in the changelog. What we test today is on [Accessibility](/accessibility).', 'accessibility issue, a11y bug, screen reader, keyboard problem, wcag issue, contrast problem', 'Support', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_copy-blocked', 'copy-blocked', 'The copy button says it was blocked by the browser.', 'Your browser refused clipboard access. Allow clipboard permission for ingotui.com, make sure the tab is focused, and click the button again. Private windows and some extensions block it; Chrome and Edge handle rich copies best.', 'copy blocked, clipboard blocked, copy not working, copy button broken, permission, browser blocked', 'Troubleshooting', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_browser-support', 'browser-support', 'Which browsers are supported?', 'Use a current version of Chrome, Edge, Safari or Firefox. Copy to Figma needs a browser that allows rich clipboard writes; if it fails, try Chrome or Edge.', 'browser, chrome, safari, firefox, edge, brave, supported browsers, old browser, mobile browser', 'Troubleshooting', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_site-slow', 'site-slow', 'The site or answers are loading slowly.', 'Reload the page. If search or answers still don''t load, write to support@ingotui.com and we''ll help directly. Our status for the MCP server is at `https://mcp.ingotui.com/health`.', 'slow, loading, not loading, site down, outage, page blank, timeout, server down', 'Troubleshooting', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_component-looks-different', 'component-looks-different', 'My copied component looks different from the preview.', 'Check three things: the `theme.css` and system CSS imports are in your global CSS, Tailwind v4 is scanning `components/ingot/`, and the font (Geist for most systems) is loaded. Other global styles in your app can also override ours.', 'looks different, wrong colors, broken layout, styles off, different from preview, misaligned, font wrong', 'Troubleshooting', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_font-setup', 'font-setup', 'Which font do I need, and how do I load it?', 'Most systems use Geist; Veriq and Abotix also use Inter and Spendix uses Manrope. Load them in your app (for example `next/font` in Next.js or a font link) and the tokens pick them up.', 'font, geist, inter, manrope, typography, font not loading, next/font', 'Troubleshooting', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_code-copy-locked', 'code-copy-locked', 'The code panel says This component is in a Pro system.', 'Its code is included in Pro, Team and Lifetime. The live preview stays free to explore. Upgrade on [Pricing](/pricing), or use the free Loopo system and templates.', 'pro system, code locked, this component is in a pro system, cant see code, upgrade to see code', 'Troubleshooting', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_login-required-error', 'login-required-error', 'I keep getting sent to sign up when I copy.', 'You''ve used the 5 guest copies in this browser or network. [Sign up free](/sign-up) or [log in](/sign-in); signed-in copies of free items are unlimited.', 'sent to sign up, redirect to signup, login required, keeps asking login', 'Troubleshooting', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_dark-mode', 'dark-mode', 'Is there dark mode?', 'Not yet. The systems are light mode today, and dark mode for all nine systems (code, charts and matching Figma variable modes) is the first update after launch. Pro, Team and Lifetime get it at no extra cost. Follow it on the [roadmap](/roadmap).', 'dark mode, dark theme, night mode, darkmode, black theme, dark version, when dark mode', 'Roadmap and updates', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_roadmap', 'roadmap', 'What''s on the roadmap?', 'Next: dark mode for all nine systems, an Agency plan with invoices, `npx ingotui audit` and a GitHub Action, starter kits per product type, Open in v0, and tables that scale. Later: SSO and a private registry, an accessibility conformance report, Figma Code Connect, Storybook and versioned packages, MCP sign-in without a key, and Vue versions. See and upvote on [Roadmap](/roadmap).', 'roadmap, upcoming, coming soon, plans, future, whats next, next features, planned', 'Roadmap and updates', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_changelog', 'changelog', 'Where can I see what''s new?', 'On the [changelog](/changelog), which also has an RSS feed. Releases list new systems, components and fixes.', 'changelog, whats new, new this week, this week, release notes, recent updates, rss', 'Roadmap and updates', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_update-frequency', 'update-frequency', 'How often are new components added?', 'Every week. Paid plans include every new component and system at no extra cost.', 'how often, new components, updates frequency, weekly, more components', 'Roadmap and updates', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_get-updates', 'get-updates', 'How do I get updates to components I already copied?', 'Copied files are yours and don''t change by themselves. To pick up a newer version, copy or install the component again (the CLI and shadcn need `--force` or overwrite to replace a file). Check the [changelog](/changelog) for what changed.', 'update component, new version, upgrade components, sync updates, pull latest', 'Roadmap and updates', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_vue-support', 'vue-support', 'Will there be Vue, Svelte or Angular versions?', 'Vue versions of the most-used components are on the [roadmap](/roadmap) under Later, if enough people ask; upvote it there. Svelte and Angular are not planned.', 'vue, nuxt, svelte, angular, solid, other frameworks', 'Roadmap and updates', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_code-connect', 'code-connect', 'Will Figma Dev Mode show the code?', 'Figma Code Connect is on the [roadmap](/roadmap) under Later.', 'code connect, dev mode, figma dev mode, inspect code', 'Roadmap and updates', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-oauth', 'mcp-oauth', 'Can I connect my agent without an API key?', 'Not yet. MCP OAuth, approving your agent in the browser instead of pasting a key, is on the [roadmap](/roadmap) under Later.', 'oauth, no api key, login agent, browser approve, mcp oauth', 'Roadmap and updates', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_vote-roadmap', 'vote-roadmap', 'How do I vote on the roadmap?', 'Press the upvote button on any item on [Roadmap](/roadmap). One vote per item; you can vote without an account.', 'vote, upvote, roadmap vote, prioritise', 'Roadmap and updates', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_privacy-data', 'privacy-data', 'What data do you collect?', 'What we need to run Ingot UI: your account (name, email, hashed password, plan, hashed API keys), what you copy and from where (website, CLI or MCP), support messages, and purchase details from Contra (payer email, plan, amount, status). We never see your card number. Full details: [Privacy Policy](/privacy).', 'privacy, data, what do you collect, personal data, tracking, information, privacy policy', 'Privacy and legal', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_privacy-sell', 'privacy-sell', 'Do you sell my data or show ads?', 'No. We don''t sell personal data or show ads. Data is processed only by the services that run Ingot UI: Cloudflare (hosting, database, MCP), Contra (payments), Google Analytics and Microsoft Clarity (only if you accept cookies).', 'sell data, ads, third parties, share data, advertising, data sharing', 'Privacy and legal', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_cookies', 'cookies', 'Which cookies do you use?', 'A sign-in session cookie, an anonymous ID cookie for the 5 free copies, and Google Analytics and Microsoft Clarity cookies that load only if you accept them in the cookie banner. Our own page counter uses no cookies and respects Do Not Track and Global Privacy Control.', 'cookies, cookie banner, analytics, google analytics, clarity, tracking, do not track, gpc, consent', 'Privacy and legal', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_data-export', 'data-export', 'Can I get a copy of my data?', 'Yes. Write to support@ingotui.com from your account email to ask for a copy, a correction or deletion. Depending on where you live, you may also complain to your data protection authority.', 'gdpr, data export, my data, data request, ccpa, access request, correct data', 'Privacy and legal', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_data-location', 'data-location', 'Where is my data stored?', 'Cloudflare hosts the site, the database and the MCP server. Payment data stays with Contra.', 'data location, where stored, servers, hosting, cloudflare, region, data residency', 'Privacy and legal', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_terms', 'terms', 'Where are the terms of service?', 'On [Terms](/terms): accounts, plans and billing through Contra, the licence, the MCP server and API keys, acceptable use and liability. The component licence itself is on [Licence](/license).', 'terms of service, tos, service agreement, conditions of use', 'Privacy and legal', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_acceptable-use', 'acceptable-use', 'Can I scrape the catalogue or share my key?', 'No. Use the MCP server and CLI with your own key and within your plan''s limits. Don''t share keys, resell access, scrape the catalogue in bulk or work around limits; abused keys may be rate-limited or suspended.', 'scrape, bulk download, share api key, abuse, resell access, automation, crawl', 'Privacy and legal', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_accessibility', 'accessibility', 'Are the components accessible?', 'We target WCAG 2.2 AA. Hand-built Loopo primitives are tested with axe-core and keyboard checks. Generated components are a pixel-accurate visual skin: swap drawn controls for real ones before you ship, and fix known gaps such as colour contrast in some tokens. Results and gaps are on [Accessibility](/accessibility).', 'accessibility, a11y, wcag, aria, screen reader, keyboard, accessible, vpat, ada, section 508', 'Privacy and legal', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_who-publishes', 'who-publishes', 'Who makes Ingot UI?', 'Ingot UI is the publisher of ingotui.com and keeps the copyright in the library. Contact: support@ingotui.com. More on [About](/about).', 'who made, company, founder, publisher, owner, who is behind, contact company', 'Privacy and legal', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_children', 'children', 'Is there an age requirement?', 'Ingot UI is a tool for professionals and is not meant for children under 16.', 'age, minimum age, children, kids, under 16', 'Privacy and legal', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
INSERT INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_warranty', 'warranty', 'Do you guarantee the components are bug-free?', 'No. The library is provided as it is. We check components against Figma and test the hand-built ones, but test what you ship. Liability limits are in the [terms](/terms#liability).', 'warranty, guarantee, liability, bug free, responsible, legal liability', 'Privacy and legal', 1, CAST(strftime('%s','now') AS INTEGER)) ON CONFLICT(`slug`) DO UPDATE SET `question` = excluded.`question`, `answer` = excluded.`answer`, `keywords` = excluded.`keywords`, `category` = excluded.`category`, `published` = 1, `updatedAt` = excluded.`updatedAt`;
